// Shared helpers for the QQ channel: OneBot v11 over a local protocol endpoint (e.g. NapCat).
// Loads ./.env (generated by `app up`) + the credentials file it names (APP_SECRETS):
//   ONEBOT_HTTP   http://127.0.0.1:3000   (actions: send_group_msg, get_login_info, ...)
//   ONEBOT_WS     ws://127.0.0.1:3001     (forward WebSocket: events)
//   ONEBOT_TOKEN  access token configured on both endpoints
//
// Conversation ids: g<group_id> for a group, u<user_id> for a private chat.
// Transcript: every message in a listened conversation is kept as one JSON line per message in
// <APP_MEMORY_DIR>/raw/<YYYY-MM-DD>.jsonl (local date), else ./transcript/. read-since reads it,
// and with app memory on it is the app's long-term memory (apps/RULES.md, persona apps).
import dotenv from 'dotenv';
import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

dotenv.config({ path: process.env.APP_ENV || '.env', quiet: true });
if (process.env.APP_SECRETS) dotenv.config({ path: process.env.APP_SECRETS, quiet: true });

export const HTTP = (process.env.ONEBOT_HTTP || 'http://127.0.0.1:3000').replace(/\/$/, '');
export const WS = process.env.ONEBOT_WS || 'ws://127.0.0.1:3001';
export const TOKEN = process.env.ONEBOT_TOKEN || '';
export const list = (v) => (v || '').split(',').map((s) => s.trim()).filter(Boolean);

export async function call(action, params = {}) {
  const r = await fetch(`${HTTP}/${action}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...(TOKEN ? { authorization: `Bearer ${TOKEN}` } : {}) },
    body: JSON.stringify(params),
    signal: AbortSignal.timeout(20_000),
  });
  if (!r.ok) throw new Error(`${action}: HTTP ${r.status}`);
  const j = await r.json();
  if (j.status === 'failed' || (j.retcode ?? 0) !== 0) throw new Error(`${action}: ${j.message || j.wording || `retcode ${j.retcode}`}`);
  return j.data;
}

export function parseConv(conv) {
  const m = /^([gu])(\d+)$/.exec(conv || '');
  if (!m) throw new Error(`bad conv '${conv}' (want g<group_id> or u<user_id>)`);
  return m[1] === 'g' ? { kind: 'group', id: Number(m[2]) } : { kind: 'private', id: Number(m[2]) };
}
export const convOf = (ev) => (ev.message_type === 'group' ? `g${ev.group_id}` : `u${ev.user_id}`);
export const senderName = (ev) => ev.sender?.card || ev.sender?.nickname || String(ev.user_id);

// OneBot message segments -> readable one-line text. Images keep their URL so the session can
// look at them (WebFetch) or mention them.
export function render(message) {
  if (typeof message === 'string') return message;
  return (message || []).map((s) => {
    const d = s.data || {};
    switch (s.type) {
      case 'text': return d.text;
      case 'at': return d.qq === 'all' ? '@全体成员' : `@${d.name || d.qq}`;
      case 'face': return '[表情]';
      case 'mface': return `[${d.summary || '表情包'}]`;
      case 'image': return `[图片${d.summary ? ` ${d.summary}` : ''} ${d.url || d.file || ''}]`;
      case 'record': return '[语音]';
      case 'video': return `[视频 ${d.url || ''}]`;
      case 'file': return `[文件 ${d.name || d.file || ''}]`;
      case 'reply': return '';
      case 'forward': return '[合并转发]';
      case 'json': return '[卡片]';
      default: return `[${s.type}]`;
    }
  }).join('').trim();
}
export const replyTo = (message) => (Array.isArray(message) ? message.find((s) => s.type === 'reply')?.data?.id ?? null : null);
export const atIds = (message) => (Array.isArray(message) ? message.filter((s) => s.type === 'at').map((s) => String(s.data?.qq)) : []);
export const files = (message) => (Array.isArray(message) ? message : [])
  .filter((s) => ['image', 'video', 'file', 'record'].includes(s.type))
  .map((s) => ({ id: String(s.data?.file_id || s.data?.file || ''), name: s.data?.file || s.data?.name || s.type, mimetype: s.type, size: Number(s.data?.file_size || 0), url: s.data?.url || null }));

// ---- transcript ---------------------------------------------------------------------------
export const transcriptDir = () => (process.env.APP_MEMORY_DIR ? join(process.env.APP_MEMORY_DIR, 'raw') : 'transcript');
const day = (epoch) => {
  const d = new Date(epoch * 1000);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};
// row: {ts, id, conv, user, name, text, self, reply_to, files}
export function record(row) {
  const dir = transcriptDir();
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true, mode: 0o700 });
  appendFileSync(join(dir, `${day(row.ts)}.jsonl`), JSON.stringify(row) + '\n', { mode: 0o600 });
}
export function rowFromEvent(ev, self) {
  return {
    ts: ev.time, id: String(ev.message_id), conv: convOf(ev), user: String(ev.user_id), name: senderName(ev),
    text: render(ev.message), self: String(ev.user_id) === String(self), reply_to: replyTo(ev.message),
    files: files(ev.message),
  };
}
// Rows of the given days (newest last). days = number of most recent day files to read.
export function readRows(days = 3) {
  const dir = transcriptDir();
  if (!existsSync(dir)) return [];
  const names = readdirSync(dir).filter((n) => /^\d{4}-\d{2}-\d{2}\.jsonl$/.test(n)).sort().slice(-days);
  const rows = [];
  for (const n of names) for (const l of readFileSync(join(dir, n), 'utf8').split('\n')) {
    if (!l) continue;
    try { rows.push(JSON.parse(l)); } catch { /* torn line */ }
  }
  const ids = new Set();                    // a post recorded by both send and the listener
  return rows.filter((r) => !ids.has(r.id) && ids.add(r.id)).sort((a, b) => a.ts - b.ts);
}
